window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a100884fcfa7d3b6"]={"versions": [{"id": "FIG-a100884fcfa7d3b6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code> (Initial State): Unbeschrifteter schwarzer Vollkreis.\n</li><li><code>J1939Tp_OFF</code>: Betriebszustand des Moduls im uninitialisierten Status.\n</li><li><code>J1939Tp_ON</code>: Betriebszustand des Moduls im voll betriebsbereiten Status.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis zur Initialisierung des Steuergeräts.\n</li><li><code>PowerDown</code>: Systemereignis zum Herunterfahren des Steuergeräts.\n</li><li><code>EcuM: J1939Tp_Init ( ) [without error]</code>: Aufruf der Initialisierungsfunktion durch den ECU State Manager mit erfolgreicher Ausführung.\n</li><li><code>J1939Tp_Init ( ) [with error]</code>: Aufruf der Initialisierungsfunktion, der mit einem Fehler fehlschlägt.\n</li><li><code>EcuM: J1939Tp_Shutdown ( )</code>: Aufruf der Shutdown-Routine durch den ECU State Manager.\n</li><li><code>J1939Tp_Shutdown()</code>: Unqualifizierter Shutdown-Aufruf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Initialknoten führt das Startereignis <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierungsversuch mit Fehler: Ein Aufruf von <code>J1939Tp_Init ( ) [with error]</code> im Zustand <code>J1939Tp_OFF</code> verbleibt über eine Selbsttransition in <code>J1939Tp_OFF</code>.\n</li><li>Unqualifizierter Shutdown: Ein Aufruf von <code>J1939Tp_Shutdown()</code> im Zustand <code>J1939Tp_OFF</code> verbleibt über eine Selbsttransition in <code>J1939Tp_OFF</code>.\n</li><li>Reguläre Initialisierung: Durch den Aufruf <code>EcuM: J1939Tp_Init ( ) [without error]</code> wechselt das Modul von <code>J1939Tp_OFF</code> in den Zustand <code>J1939Tp_ON</code>.\n</li><li>Geordnetes Herunterfahren: Durch den Aufruf <code>EcuM: J1939Tp_Shutdown ( )</code> wechselt das Modul von <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Sowohl aus <code>J1939Tp_OFF</code> als auch direkt aus <code>J1939Tp_ON</code> führt das Ereignis <code>PowerDown</code> in den Endzustand (Terminierung).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modul darf erst nach erfolgreicher Initialisierung (<code>[without error]</code>) Daten über SAE J1939 transportieren. Tritt bei <code>J1939Tp_Init</code> ein Fehler auf, verbleibt das Modul in <code>J1939Tp_OFF</code>, sodass keine Transportprotokollfunktionen aktiv werden. Der Aufrufer der Lebenszyklus-Schnittstellen ist der <code>EcuM</code>. Ein <code>PowerDown</code>-Ereignis kann das Modul direkt aus beiden Betriebszuständen beenden.</p>"}, {"id": "FIG-e84ee987146da2eb", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code>: Explizit beschrifteter Initialknoten (schwarzer Vollkreis).\n</li><li><code>J1939Tp_OFF</code>: Uninitialisierter Betriebszustand des Moduls.\n</li><li><code>J1939Tp_ON</code>: Initialisierter, aktiver Betriebszustand des Moduls.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis beim Hochfahren der ECU.\n</li><li><code>PowerDown</code>: Systemereignis beim Abschalten der ECU.\n</li><li><code>EcuM: J1939Tp_Init (without error)</code>: Initialisierungsaufruf durch den ECU State Manager ohne Fehler.\n</li><li><code>EcuM: J1939Tp_Shutdown</code>: Shutdown-Aufruf durch den ECU State Manager.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Knoten <code>Initial</code> führt die Transition <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierung: Über den Aufruf <code>EcuM: J1939Tp_Init (without error)</code> wechselt das Modul von <code>J1939Tp_OFF</code> nach <code>J1939Tp_ON</code>.\n</li><li>Herunterfahren: Der Aufruf <code>EcuM: J1939Tp_Shutdown</code> überführt das Modul aus <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Über das Ereignis <code>PowerDown</code> kann das Modul sowohl aus <code>J1939Tp_OFF</code> als auch aus <code>J1939Tp_ON</code> direkt den Endzustand erreichen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellen <code>J1939Tp_Init</code> und <code>J1939Tp_Shutdown</code> werden strikt durch den <code>EcuM</code> angesteuert. Ein fehlerhafter Initialisierungsaufruf sowie ein Shutdown im uninitialisierten Zustand besitzen keine modellierten Selbsttransitionen mehr im Diagramm. Für Entwickler gilt: Erst nach fehlerfreiem Durchlauf von <code>J1939Tp_Init</code> befindet sich das Modul im Zustand <code>J1939Tp_ON</code>. Ein <code>PowerDown</code> führt aus beiden Zuständen zur Terminierung.</p>"}, {"id": "FIG-ac6a1f40eb7c7ea7", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code>: Explizit beschrifteter Initialknoten (schwarzer Vollkreis).\n</li><li><code>J1939Tp_OFF</code>: Uninitialisierter Betriebszustand des Moduls.\n</li><li><code>J1939Tp_ON</code>: Initialisierter, aktiver Betriebszustand des Moduls.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis beim Hochfahren der ECU.\n</li><li><code>PowerDown</code>: Systemereignis beim Abschalten der ECU.\n</li><li><code>EcuM: J1939Tp_Init (without error)</code>: Initialisierungsaufruf durch den ECU State Manager ohne Fehler.\n</li><li><code>EcuM: J1939Tp_Shutdown</code>: Shutdown-Aufruf durch den ECU State Manager.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Knoten <code>Initial</code> führt die Transition <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierung: Über den Aufruf <code>EcuM: J1939Tp_Init (without error)</code> wechselt das Modul von <code>J1939Tp_OFF</code> nach <code>J1939Tp_ON</code>.\n</li><li>Herunterfahren: Der Aufruf <code>EcuM: J1939Tp_Shutdown</code> überführt das Modul aus <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Über das Ereignis <code>PowerDown</code> kann das Modul sowohl aus <code>J1939Tp_OFF</code> als auch aus <code>J1939Tp_ON</code> direkt den Endzustand erreichen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellen <code>J1939Tp_Init</code> und <code>J1939Tp_Shutdown</code> werden strikt durch den <code>EcuM</code> angesteuert. Ein fehlerhafter Initialisierungsaufruf sowie ein Shutdown im uninitialisierten Zustand besitzen keine modellierten Selbsttransitionen mehr im Diagramm. Für Entwickler gilt: Erst nach fehlerfreiem Durchlauf von <code>J1939Tp_Init</code> befindet sich das Modul im Zustand <code>J1939Tp_ON</code>. Ein <code>PowerDown</code> führt aus beiden Zuständen zur Terminierung.</p>"}, {"id": "FIG-3e4f8ec6e04dd527", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code>: Explizit beschrifteter Initialknoten (schwarzer Vollkreis).\n</li><li><code>J1939Tp_OFF</code>: Uninitialisierter Betriebszustand des Moduls.\n</li><li><code>J1939Tp_ON</code>: Initialisierter, aktiver Betriebszustand des Moduls.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis beim Hochfahren der ECU.\n</li><li><code>PowerDown</code>: Systemereignis beim Abschalten der ECU.\n</li><li><code>EcuM: J1939Tp_Init (without error)</code>: Initialisierungsaufruf durch den ECU State Manager ohne Fehler.\n</li><li><code>EcuM: J1939Tp_Shutdown</code>: Shutdown-Aufruf durch den ECU State Manager.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Knoten <code>Initial</code> führt die Transition <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierung: Über den Aufruf <code>EcuM: J1939Tp_Init (without error)</code> wechselt das Modul von <code>J1939Tp_OFF</code> nach <code>J1939Tp_ON</code>.\n</li><li>Herunterfahren: Der Aufruf <code>EcuM: J1939Tp_Shutdown</code> überführt das Modul aus <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Über das Ereignis <code>PowerDown</code> kann das Modul sowohl aus <code>J1939Tp_OFF</code> als auch aus <code>J1939Tp_ON</code> direkt den Endzustand erreichen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellen <code>J1939Tp_Init</code> und <code>J1939Tp_Shutdown</code> werden strikt durch den <code>EcuM</code> angesteuert. Ein fehlerhafter Initialisierungsaufruf sowie ein Shutdown im uninitialisierten Zustand besitzen keine modellierten Selbsttransitionen mehr im Diagramm. Für Entwickler gilt: Erst nach fehlerfreiem Durchlauf von <code>J1939Tp_Init</code> befindet sich das Modul im Zustand <code>J1939Tp_ON</code>. Ein <code>PowerDown</code> führt aus beiden Zuständen zur Terminierung.</p>"}, {"id": "FIG-d25f3fb406173a8d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code>: Explizit beschrifteter Initialknoten (schwarzer Vollkreis).\n</li><li><code>J1939Tp_OFF</code>: Uninitialisierter Betriebszustand des Moduls.\n</li><li><code>J1939Tp_ON</code>: Initialisierter, aktiver Betriebszustand des Moduls.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis beim Hochfahren der ECU.\n</li><li><code>PowerDown</code>: Systemereignis beim Abschalten der ECU.\n</li><li><code>EcuM: J1939Tp_Init (without error)</code>: Initialisierungsaufruf durch den ECU State Manager ohne Fehler.\n</li><li><code>EcuM: J1939Tp_Shutdown</code>: Shutdown-Aufruf durch den ECU State Manager.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Knoten <code>Initial</code> führt die Transition <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierung: Über den Aufruf <code>EcuM: J1939Tp_Init (without error)</code> wechselt das Modul von <code>J1939Tp_OFF</code> nach <code>J1939Tp_ON</code>.\n</li><li>Herunterfahren: Der Aufruf <code>EcuM: J1939Tp_Shutdown</code> überführt das Modul aus <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Über das Ereignis <code>PowerDown</code> kann das Modul sowohl aus <code>J1939Tp_OFF</code> als auch aus <code>J1939Tp_ON</code> direkt den Endzustand erreichen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellen <code>J1939Tp_Init</code> und <code>J1939Tp_Shutdown</code> werden strikt durch den <code>EcuM</code> angesteuert. Ein fehlerhafter Initialisierungsaufruf sowie ein Shutdown im uninitialisierten Zustand besitzen keine modellierten Selbsttransitionen mehr im Diagramm. Für Entwickler gilt: Erst nach fehlerfreiem Durchlauf von <code>J1939Tp_Init</code> befindet sich das Modul im Zustand <code>J1939Tp_ON</code>. Ein <code>PowerDown</code> führt aus beiden Zuständen zur Terminierung.</p>"}, {"id": "FIG-746949c8f666b338", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code>: Explizit beschrifteter Initialknoten (schwarzer Vollkreis).\n</li><li><code>J1939Tp_OFF</code>: Uninitialisierter Betriebszustand des Moduls.\n</li><li><code>J1939Tp_ON</code>: Initialisierter, aktiver Betriebszustand des Moduls.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis beim Hochfahren der ECU.\n</li><li><code>PowerDown</code>: Systemereignis beim Abschalten der ECU.\n</li><li><code>EcuM: J1939Tp_Init (without error)</code>: Initialisierungsaufruf durch den ECU State Manager ohne Fehler.\n</li><li><code>EcuM: J1939Tp_Shutdown</code>: Shutdown-Aufruf durch den ECU State Manager.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Knoten <code>Initial</code> führt die Transition <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierung: Über den Aufruf <code>EcuM: J1939Tp_Init (without error)</code> wechselt das Modul von <code>J1939Tp_OFF</code> nach <code>J1939Tp_ON</code>.\n</li><li>Herunterfahren: Der Aufruf <code>EcuM: J1939Tp_Shutdown</code> überführt das Modul aus <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Über das Ereignis <code>PowerDown</code> kann das Modul sowohl aus <code>J1939Tp_OFF</code> als auch aus <code>J1939Tp_ON</code> direkt den Endzustand erreichen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellen <code>J1939Tp_Init</code> und <code>J1939Tp_Shutdown</code> werden strikt durch den <code>EcuM</code> angesteuert. Ein fehlerhafter Initialisierungsaufruf sowie ein Shutdown im uninitialisierten Zustand besitzen keine modellierten Selbsttransitionen mehr im Diagramm. Für Entwickler gilt: Erst nach fehlerfreiem Durchlauf von <code>J1939Tp_Init</code> befindet sich das Modul im Zustand <code>J1939Tp_ON</code>. Ein <code>PowerDown</code> führt aus beiden Zuständen zur Terminierung.</p>"}, {"id": "FIG-2fa455c804057551", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Lebenszyklus des AUTOSAR Classic BSW-Moduls <code>J1939Tp</code> (SAE J1939 Transport Layer). Das Diagramm verortet das Modul im Zusammenspiel mit dem ECU State Manager (<code>EcuM</code>) und visualisiert die Betriebsmodi im Kommunikationsstack.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände und Knoten:</p>\n<ul class=\"fig-list\"><li><code>Initial</code>: Explizit beschrifteter Initialknoten (schwarzer Vollkreis).\n</li><li><code>J1939Tp_OFF</code>: Uninitialisierter Betriebszustand des Moduls.\n</li><li><code>J1939Tp_ON</code>: Initialisierter, aktiver Betriebszustand des Moduls.\n</li><li>Final State / Termination: Durchkreuzter Kreis (Zustandsabschluss).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Triggerevents:</p>\n<ul class=\"fig-list\"><li><code>PowerUp</code>: Systemereignis beim Hochfahren der ECU.\n</li><li><code>PowerDown</code>: Systemereignis beim Abschalten der ECU.\n</li><li><code>EcuM: J1939Tp_Init (without error)</code>: Initialisierungsaufruf durch den ECU State Manager ohne Fehler.\n</li><li><code>EcuM: J1939Tp_Shutdown</code>: Shutdown-Aufruf durch den ECU State Manager.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Systemstart: Ausgehend vom Knoten <code>Initial</code> führt die Transition <code>PowerUp</code> direkt in den Zustand <code>J1939Tp_OFF</code>.\n</li><li>Initialisierung: Über den Aufruf <code>EcuM: J1939Tp_Init (without error)</code> wechselt das Modul von <code>J1939Tp_OFF</code> nach <code>J1939Tp_ON</code>.\n</li><li>Herunterfahren: Der Aufruf <code>EcuM: J1939Tp_Shutdown</code> überführt das Modul aus <code>J1939Tp_ON</code> zurück in <code>J1939Tp_OFF</code>.\n</li><li>Terminierung: Über das Ereignis <code>PowerDown</code> kann das Modul sowohl aus <code>J1939Tp_OFF</code> als auch aus <code>J1939Tp_ON</code> direkt den Endzustand erreichen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstellen <code>J1939Tp_Init</code> und <code>J1939Tp_Shutdown</code> werden strikt durch den <code>EcuM</code> angesteuert. Ein fehlerhafter Initialisierungsaufruf sowie ein Shutdown im uninitialisierten Zustand besitzen keine modellierten Selbsttransitionen mehr im Diagramm. Für Entwickler gilt: Erst nach fehlerfreiem Durchlauf von <code>J1939Tp_Init</code> befindet sich das Modul im Zustand <code>J1939Tp_ON</code>. Ein <code>PowerDown</code> führt aus beiden Zuständen zur Terminierung.</p>"}], "trans": [{"from": "FIG-a100884fcfa7d3b6", "to": "FIG-e84ee987146da2eb", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Übergang <code>J1939Tp_Init ( ) [with error]</code> (Selbsttransition an <code>J1939Tp_OFF</code>): entfällt.\n</li><li>Übergang <code>J1939Tp_Shutdown()</code> (Selbsttransition an <code>J1939Tp_OFF</code>): entfällt.\n</li><li>Pseudozustand <code>Initial</code>: Beschriftung am Initialknoten ergänzt.\n</li><li>Initial-Transition: Pfeil führt nun horizontal von <code>Initial</code> nach <code>J1939Tp_OFF</code>.\n</li><li>Übergang <code>EcuM: J1939Tp_Init ( ) [without error]</code> zu <code>J1939Tp_ON</code>: Schreibweise auf <code>EcuM: J1939Tp_Init\\n(without error)</code> geändert.\n</li><li>Übergang <code>EcuM: J1939Tp_Shutdown ( )</code> zu <code>J1939Tp_OFF</code>: Schreibweise auf <code>EcuM: J1939Tp_Shutdown</code> geändert (Klammern entfallen).\n</li><li>Diagramm-Rahmen: umlaufender Rahmen entfällt.\n</li></ul>"}, {"from": "FIG-e84ee987146da2eb", "to": "FIG-ac6a1f40eb7c7ea7", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac6a1f40eb7c7ea7", "to": "FIG-3e4f8ec6e04dd527", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e4f8ec6e04dd527", "to": "FIG-d25f3fb406173a8d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d25f3fb406173a8d", "to": "FIG-746949c8f666b338", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-746949c8f666b338", "to": "FIG-2fa455c804057551", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
